{"command":"python - << 'PY'
import chess, chess.engine, os
board = chess.Board('3r2k1/5pp1/p1q4p/1pp1Q3/8/2P2N2/PP3PPP/4R1K1 b - - 5 25')
engine = chess.engine.SimpleEngine.popen_uci('/usr/local/bin/stockfish')
for mv in ['Re8','d4','Qd6','Qb6','Qe6','f6']:
    try:
        move=board.parse_san(mv)
    except:
        continue
    info=engine.analyse(board,chess.engine.Limit(depth=12),root_moves=[move])
    print(mv, info['score'])
engine.quit()
